const lifeSpecs = {
  app: { name: 'Web application', role: 'Confidential OIDC relying party', plainRole: 'Keeps its credentials, tokens and application session on its backend.', notes: ['Protocol values are symbolic; no live authentication occurs.', 'Client credentials stay off the browser; ID tokens are never API credentials.'], art: 'webapp' },
  realmA: { name: 'Keycloak · Realm A', role: 'OIDC provider / authorization server', plainRole: 'Checks grants and session policy, issues tokens and ends provider sessions.', notes: ['Session, rotation and revocation rules depend on configured policy.', 'Private issuer signing keys remain inside the provider.'] },
  user: { name: 'Person', role: 'Account holder', plainRole: 'Uses the authenticated application and can authorize offline access or sign out.', notes: ['These scenarios start with the stated existing account/session conditions.'] },
  browser: { name: 'Browser', role: 'User agent', plainRole: 'Carries authorization/logout redirects and origin-scoped cookies.', notes: ['Cookies and iframe behavior depend on browser policy.', 'It never receives the confidential client secret or refresh credentials.'] },
};
// Resolve symbolic examples at construction time, retaining the preceding value in
// this story unless this step explicitly changes it. Every step receives its own
// snapshot, so a recipient's later event cannot rewrite an earlier focused trace.
const lifeStoryValues = new Map();
const lifeStep = (story, key, title, from, to, phase, channel, summary, detail, ops, data = [], checks = [], values = {}) => {
  const fields = [...new Set(ops.map(op => op.attributeId))];
  const explicit = Object.fromEntries(data.filter(member => member.attributeId && !member.lifeExampleFallback).map(member => [member.attributeId, member.value]));
  const context = { ...lifeStoryValues.get(story), ...explicit, ...values };
  const payload = data.map(({ lifeExampleFallback, ...member }) => lifeExampleFallback && Object.hasOwn(context, member.attributeId) ? { ...member, value: context[member.attributeId] } : member);
  const attributeValues = Object.fromEntries(fields.map(id => [id, context[id] ?? LIFELAB_ATTRIBUTES[id].example]));
  for (const member of payload) if (member.attributeId) attributeValues[member.attributeId] = member.value;
  lifeStoryValues.set(story, { ...context, ...attributeValues });
  return { ...labStep(story + '-' + key, title, from, to, phase, channel, summary, detail, fields, payload, checks, ops), attributeValues };
};
const lifePayload = (id, value, description) => ({ ...labP(LIFELAB_ATTRIBUTES[id].name, value ?? LIFELAB_ATTRIBUTES[id].example, description, id), ...(value == null ? { lifeExampleFallback: true } : {}) });
const lifePayloads = (ids, values = {}) => ids.map(id => lifePayload(id, values[id]));
const lifeUse = (ids, actor, detail) => labOp(ids, 'use', actor, detail);
const lifeVerify = (ids, actor, detail) => labOp(ids, 'verify', actor, detail);
const lifeCreate = (ids, actor, detail) => labOp(ids, 'create', actor, detail);
const lifeDerive = (ids, actor, detail) => labOp(ids, 'derive', actor, detail);
const lifeStore = (ids, actor, detail) => labOp(ids, 'store', actor, detail);
const lifeWire = (ids, from, to, detail, carrier) => labWire(ids, from, to, detail, carrier);
const lifeCredentialOps = (to = 'realmA') => [...lifeWire(['lifeBasic'], 'app', to, 'HTTP Basic client authentication over TLS.', 'HTTP Authorization header'), ...lifeWire(['lifeClientId', 'lifeClientSecret'], 'app', to, 'Encoded confidential-client credentials inside the Basic header, never separate body members in this profile.', 'Authorization: Basic over HTTPS')];
const lifeCredentialPreparation = [...lifeUse(['lifeClientId', 'lifeClientSecret', 'lifeTokenEndpoint'], 'app', 'Reads the protected confidential-client registration and trusted endpoint.'), ...lifeDerive(['lifeBasic'], 'app', 'Constructs Basic from form-encoded credentials, then Base64 encodes them; HTTPS supplies confidentiality.')];
const lifeIdentityClaims = ['lifeIdIssuer', 'lifeIdSubject', 'lifeIdAudience', 'lifeIdIssuedAt', 'lifeIdExpiresAt', 'lifeAuthTime'];
const lifeRefreshFields = ['lifeAccessToken', 'lifeIdToken', 'lifeReplacementRefresh', 'lifeTokenType', 'lifeExpiresIn', 'lifeScope'];
const lifeAuthorizationFields = ['lifeClientId', 'lifeRedirect', 'lifeResponseType', 'lifeScope', 'lifeState', 'lifeNonce', 'lifeChallenge', 'lifeChallengeMethod'];
